{
  "name": "Family OS",
  "description": "A comprehensive iPad-optimized Family Operating System for wall-mounted or tablet use, featuring scheduling, meal planning, and task management."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum Category {
  FAMILY = 'Family',
  WORK = 'Work',
  KIDS = 'Kids',
  BILLS = 'Bills'
}

export interface CalendarEvent {
  id: string;
  title: string;
  date: string;
  category: Category;
}

export interface GroceryItem {
  id: string;
  text: string;
  completed: boolean;
  aisle: string;
}

export interface TaskItem {
  id: string;
  text: string;
  completed: boolean;
}

export interface MealPlan {
  day: string;
  lunch: string;
  dinner: string;
}

export type View = 'dashboard' | 'calendar' | 'groceries' | 'meals' | 'info';

import React from 'react';
import { LayoutDashboard, Calendar, ShoppingCart, Utensils, Info } from 'lucide-react';
import { Category, View } from './types';

export const NAV_ITEMS = [
  { id: 'dashboard' as View, label: 'Home', icon: <LayoutDashboard size={28} /> },
  { id: 'calendar' as View, label: 'Calendar', icon: <Calendar size={28} /> },
  { id: 'groceries' as View, label: 'Tasks', icon: <ShoppingCart size={28} /> },
  { id: 'meals' as View, label: 'Meals', icon: <Utensils size={28} /> },
  { id: 'info' as View, label: 'Info Hub', icon: <Info size={28} /> },
];

export const CATEGORY_COLORS: Record<Category, string> = {
  [Category.FAMILY]: 'bg-blue-500',
  [Category.WORK]: 'bg-purple-500',
  [Category.KIDS]: 'bg-green-500',
  [Category.BILLS]: 'bg-red-500',
};

export const AISLES = ['Produce', 'Dairy', 'Meat', 'Pantry', 'Frozen', 'Household', 'Other'];

import React, { useState, useEffect } from 'react';
import { NAV_ITEMS } from './constants';
import { View, CalendarEvent, GroceryItem, TaskItem, MealPlan, Category } from './types';
import Dashboard from './components/Dashboard';
import CalendarView from './components/CalendarView';
import TasksView from './components/TasksView';
import MealsView from './components/MealsView';
import InfoHub from './components/InfoHub';

const App: React.FC = () => {
  const [activeView, setActiveView] = useState<View>('dashboard');

  // Persisted States
  const [events, setEvents] = useState<CalendarEvent[]>(() => {
    const saved = localStorage.getItem('family_events');
    return saved ? JSON.parse(saved) : [
      { id: '1', title: 'Soccer Practice', date: new Date().toISOString().split('T')[0], category: Category.KIDS },
      { id: '2', title: 'Dinner with Grandparents', date: new Date().toISOString().split('T')[0], category: Category.FAMILY },
    ];
  });

  const [groceries, setGroceries] = useState<GroceryItem[]>(() => {
    const saved = localStorage.getItem('family_groceries');
    return saved ? JSON.parse(saved) : [
      { id: '1', text: 'Milk', completed: false, aisle: 'Dairy' },
      { id: '2', text: 'Apples', completed: true, aisle: 'Produce' },
    ];
  });

  const [tasks, setTasks] = useState<TaskItem[]>(() => {
    const saved = localStorage.getItem('family_tasks');
    return saved ? JSON.parse(saved) : [
      { id: '1', text: 'Take out trash', completed: false },
    ];
  });

  const [meals, setMeals] = useState<MealPlan[]>(() => {
    const saved = localStorage.getItem('family_meals');
    if (saved) return JSON.parse(saved);
    const days = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'];
    return days.map(day => ({ day, lunch: '', dinner: '' }));
  });

  const [quickNote, setQuickNote] = useState(() => localStorage.getItem('family_note') || "Dad is napping. Keep it quiet!");

  // Sync to LocalStorage
  useEffect(() => localStorage.setItem('family_events', JSON.stringify(events)), [events]);
  useEffect(() => localStorage.setItem('family_groceries', JSON.stringify(groceries)), [groceries]);
  useEffect(() => localStorage.setItem('family_tasks', JSON.stringify(tasks)), [tasks]);
  useEffect(() => localStorage.setItem('family_meals', JSON.stringify(meals)), [meals]);
  useEffect(() => localStorage.setItem('family_note', quickNote), [quickNote]);

  const renderContent = () => {
    switch (activeView) {
      case 'dashboard':
        return <Dashboard events={events} meals={meals} quickNote={quickNote} setQuickNote={setQuickNote} />;
      case 'calendar':
        return <CalendarView events={events} setEvents={setEvents} />;
      case 'groceries':
        return <TasksView groceries={groceries} setGroceries={setGroceries} tasks={tasks} setTasks={setTasks} />;
      case 'meals':
        return <MealsView meals={meals} setMeals={setMeals} />;
      case 'info':
        return <InfoHub />;
      default:
        return <Dashboard events={events} meals={meals} quickNote={quickNote} setQuickNote={setQuickNote} />;
    }
  };

  return (
    <div className="flex h-screen w-screen overflow-hidden bg-black text-white p-4 gap-4">
      {/* Sidebar Navigation */}
      <nav className="w-24 md:w-32 flex flex-col items-center glass rounded-3xl py-8 space-y-8">
        <div className="mb-4">
          <div className="w-12 h-12 bg-gradient-to-tr from-blue-500 to-indigo-600 rounded-2xl flex items-center justify-center shadow-lg shadow-blue-500/20">
            <span className="font-bold text-xl">F</span>
          </div>
        </div>
        {NAV_ITEMS.map((item) => (
          <button
            key={item.id}
            onClick={() => setActiveView(item.id)}
            className={`p-4 rounded-2xl transition-all duration-200 flex flex-col items-center gap-2 w-20 ${
              activeView === item.id 
                ? 'glass-active text-blue-400 shadow-inner' 
                : 'text-gray-400 hover:text-white hover:bg-white/5'
            }`}
          >
            {item.icon}
            <span className="text-[10px] font-medium uppercase tracking-wider">{item.label}</span>
          </button>
        ))}
      </nav>

      {/* Main Content Area */}
      <main className="flex-1 glass rounded-3xl overflow-hidden relative">
        <div className="h-full w-full overflow-y-auto p-8">
          {renderContent()}
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { CalendarEvent, MealPlan } from '../types';
import { Cloud, Clock, Utensils, Edit3 } from 'lucide-react';

interface Props {
  events: CalendarEvent[];
  meals: MealPlan[];
  quickNote: string;
  setQuickNote: (note: string) => void;
}

const Dashboard: React.FC<Props> = ({ events, meals, quickNote, setQuickNote }) => {
  const [time, setTime] = useState(new Date());

  useEffect(() => {
    const timer = setInterval(() => setTime(new Date()), 1000);
    return () => clearInterval(timer);
  }, []);

  const todayStr = new Date().toLocaleDateString('en-US', { weekday: 'long' });
  const todaysMeals = meals.find(m => m.day === todayStr);
  const todaysEvents = events.filter(e => e.date === new Date().toISOString().split('T')[0]).slice(0, 3);

  return (
    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 grid-rows-2 gap-6 h-full">
      {/* At a Glance */}
      <div className="glass rounded-3xl p-6 flex flex-col justify-between shadow-xl">
        <div className="flex justify-between items-start">
          <div>
            <h2 className="text-4xl font-bold">{time.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</h2>
            <p className="text-gray-400 font-medium mt-1">
              {time.toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric' })}
            </p>
          </div>
          <div className="text-right">
            <div className="flex items-center gap-2 text-blue-400 font-bold text-2xl">
              <Cloud />
              72°F
            </div>
            <p className="text-gray-400 text-sm">Sunny • Palo Alto</p>
          </div>
        </div>
        <div className="mt-8 flex gap-2">
            <div className="h-2 w-12 bg-blue-500 rounded-full"></div>
            <div className="h-2 w-8 bg-white/20 rounded-full"></div>
            <div className="h-2 w-8 bg-white/20 rounded-full"></div>
        </div>
      </div>

      {/* Today's Focus */}
      <div className="glass rounded-3xl p-6 flex flex-col shadow-xl">
        <div className="flex items-center gap-3 mb-6">
          <Clock className="text-orange-400" />
          <h3 className="text-xl font-bold tracking-tight">Today's Focus</h3>
        </div>
        <div className="space-y-4">
          {todaysEvents.length > 0 ? todaysEvents.map(event => (
            <div key={event.id} className="flex items-center gap-4 bg-white/5 p-4 rounded-2xl border border-white/5">
              <div className={`w-1.5 h-10 rounded-full ${
                event.category === 'Kids' ? 'bg-green-500' : 
                event.category === 'Work' ? 'bg-purple-500' : 'bg-blue-500'
              }`}></div>
              <div>
                <p className="font-semibold text-lg leading-none mb-1">{event.title}</p>
                <p className="text-sm text-gray-400">{event.category}</p>
              </div>
            </div>
          )) : (
            <div className="text-gray-500 italic py-4">No events scheduled for today.</div>
          )}
        </div>
      </div>

      {/* Dinner Tonight */}
      <div className="glass rounded-3xl p-6 flex flex-col justify-between shadow-xl">
        <div className="flex items-center gap-3 mb-4">
          <Utensils className="text-pink-400" />
          <h3 className="text-xl font-bold tracking-tight">Dinner Tonight</h3>
        </div>
        <div className="bg-gradient-to-br from-pink-500/20 to-orange-500/20 p-6 rounded-2xl border border-pink-500/20 flex-1 flex flex-col justify-center items-center text-center">
          <p className="text-3xl font-bold text-white mb-2">
            {todaysMeals?.dinner || "Not decided yet"}
          </p>
          <p className="text-pink-400 font-medium">Click Meal Planner to update</p>
        </div>
      </div>

      {/* Quick Notes */}
      <div className="glass rounded-3xl p-6 flex flex-col lg:col-span-3 shadow-xl">
        <div className="flex items-center justify-between mb-4">
          <div className="flex items-center gap-3">
            <Edit3 className="text-yellow-400" />
            <h3 className="text-xl font-bold tracking-tight">Family Scratchpad</h3>
          </div>
          <span className="text-xs text-gray-500 uppercase font-bold tracking-widest">Digital Sticky Note</span>
        </div>
        <textarea
          value={quickNote}
          onChange={(e) => setQuickNote(e.target.value)}
          className="flex-1 bg-white/5 rounded-2xl p-6 text-xl text-yellow-100/80 outline-none focus:ring-2 ring-yellow-500/30 resize-none font-medium placeholder:text-gray-700 shadow-inner"
          placeholder="Leave a message for the family..."
        />
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState } from 'react';
import { CalendarEvent, Category } from '../types';
import { ChevronLeft, ChevronRight, Plus } from 'lucide-react';
import { CATEGORY_COLORS } from '../constants';

interface Props {
  events: CalendarEvent[];
  setEvents: React.Dispatch<React.SetStateAction<CalendarEvent[]>>;
}

const CalendarView: React.FC<Props> = ({ events, setEvents }) => {
  const [currentDate, setCurrentDate] = useState(new Date());
  const [showModal, setShowModal] = useState(false);
  const [newEvent, setNewEvent] = useState({ title: '', category: Category.FAMILY, date: '' });

  const getDaysInMonth = (year: number, month: number) => new Date(year, month + 1, 0).getDate();
  const getFirstDayOfMonth = (year: number, month: number) => new Date(year, month, 1).getDay();

  const handlePrevMonth = () => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() - 1, 1));
  const handleNextMonth = () => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() + 1, 1));

  const daysInMonth = getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth());
  const firstDay = getFirstDayOfMonth(currentDate.getFullYear(), currentDate.getMonth());
  const monthName = currentDate.toLocaleString('default', { month: 'long' });
  const year = currentDate.getFullYear();

  const handleAddEvent = () => {
    if (!newEvent.title || !newEvent.date) return;
    setEvents(prev => [...prev, { ...newEvent, id: Date.now().toString() }]);
    setNewEvent({ title: '', category: Category.FAMILY, date: '' });
    setShowModal(false);
  };

  return (
    <div className="h-full flex flex-col">
      <div className="flex items-center justify-between mb-8">
        <div className="flex items-center gap-6">
          <h2 className="text-3xl font-bold">{monthName} <span className="text-gray-500">{year}</span></h2>
          <div className="flex gap-2">
            <button onClick={handlePrevMonth} className="p-3 glass rounded-xl hover:bg-white/10 transition-colors">
              <ChevronLeft size={24} />
            </button>
            <button onClick={handleNextMonth} className="p-3 glass rounded-xl hover:bg-white/10 transition-colors">
              <ChevronRight size={24} />
            </button>
          </div>
        </div>
        <button 
          onClick={() => setShowModal(true)}
          className="bg-blue-600 hover:bg-blue-500 text-white px-6 py-4 rounded-2xl flex items-center gap-3 font-bold transition-all transform active:scale-95 shadow-lg shadow-blue-600/20"
        >
          <Plus size={24} />
          Add Event
        </button>
      </div>

      <div className="flex-1 grid grid-cols-7 gap-px bg-white/10 rounded-3xl overflow-hidden border border-white/10">
        {['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'].map(day => (
          <div key={day} className="bg-white/5 p-4 text-center font-bold text-gray-400 text-xs uppercase tracking-widest">{day}</div>
        ))}
        {Array.from({ length: firstDay }).map((_, i) => (
          <div key={`empty-${i}`} className="bg-white/5 min-h-[120px]"></div>
        ))}
        {Array.from({ length: daysInMonth }).map((_, i) => {
          const day = i + 1;
          const dateStr = `${year}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
          const dayEvents = events.filter(e => e.date === dateStr);

          return (
            <div key={day} className="bg-white/5 min-h-[120px] p-2 hover:bg-white/10 transition-colors group">
              <span className="text-sm font-semibold ml-2 mt-2 inline-block opacity-60 group-hover:opacity-100">{day}</span>
              <div className="mt-2 space-y-1">
                {dayEvents.map(event => (
                  <div key={event.id} className={`${CATEGORY_COLORS[event.category]} text-[10px] px-2 py-1 rounded-md font-bold truncate`}>
                    {event.title}
                  </div>
                ))}
              </div>
            </div>
          );
        })}
      </div>

      {showModal && (
        <div className="fixed inset-0 bg-black/80 backdrop-blur-sm flex items-center justify-center z-50 p-4">
          <div className="glass rounded-3xl p-8 w-full max-w-lg border border-white/20 shadow-2xl">
            <h3 className="text-2xl font-bold mb-6">New Family Event</h3>
            <div className="space-y-6">
              <div>
                <label className="block text-sm font-bold text-gray-400 mb-2 uppercase tracking-wider">Event Name</label>
                <input 
                  type="text" 
                  value={newEvent.title}
                  onChange={(e) => setNewEvent(prev => ({ ...prev, title: e.target.value }))}
                  className="w-full bg-white/10 rounded-2xl p-4 outline-none border border-white/10 focus:border-blue-500 transition-colors"
                  placeholder="e.g., Dentist Appointment"
                />
              </div>
              <div>
                <label className="block text-sm font-bold text-gray-400 mb-2 uppercase tracking-wider">Date</label>
                <input 
                  type="date" 
                  value={newEvent.date}
                  onChange={(e) => setNewEvent(prev => ({ ...prev, date: e.target.value }))}
                  className="w-full bg-white/10 rounded-2xl p-4 outline-none border border-white/10 focus:border-blue-500 transition-colors"
                />
              </div>
              <div>
                <label className="block text-sm font-bold text-gray-400 mb-2 uppercase tracking-wider">Category</label>
                <div className="grid grid-cols-2 gap-3">
                  {Object.values(Category).map(cat => (
                    <button
                      key={cat}
                      onClick={() => setNewEvent(prev => ({ ...prev, category: cat }))}
                      className={`p-4 rounded-2xl border transition-all ${
                        newEvent.category === cat 
                          ? `${CATEGORY_COLORS[cat]} border-white text-white` 
                          : 'bg-white/5 border-white/5 text-gray-400 hover:bg-white/10'
                      }`}
                    >
                      {cat}
                    </button>
                  ))}
                </div>
              </div>
              <div className="flex gap-4 pt-4">
                <button 
                  onClick={() => setShowModal(false)}
                  className="flex-1 bg-white/5 hover:bg-white/10 py-4 rounded-2xl font-bold transition-colors"
                >
                  Cancel
                </button>
                <button 
                  onClick={handleAddEvent}
                  className="flex-1 bg-blue-600 hover:bg-blue-500 py-4 rounded-2xl font-bold shadow-lg shadow-blue-600/20"
                >
                  Save Event
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default CalendarView;

import React, { useState } from 'react';
import { GroceryItem, TaskItem } from '../types';
import { AISLES } from '../constants';
import { Plus, Trash2, CheckCircle2, Circle } from 'lucide-react';

interface Props {
  groceries: GroceryItem[];
  setGroceries: React.Dispatch<React.SetStateAction<GroceryItem[]>>;
  tasks: TaskItem[];
  setTasks: React.Dispatch<React.SetStateAction<TaskItem[]>>;
}

const TasksView: React.FC<Props> = ({ groceries, setGroceries, tasks, setTasks }) => {
  const [newGrocery, setNewGrocery] = useState('');
  const [newAisle, setNewAisle] = useState('Produce');
  const [newTask, setNewTask] = useState('');

  const addGrocery = () => {
    if (!newGrocery) return;
    setGroceries(prev => [{ id: Date.now().toString(), text: newGrocery, aisle: newAisle, completed: false }, ...prev]);
    setNewGrocery('');
  };

  const addTask = () => {
    if (!newTask) return;
    setTasks(prev => [{ id: Date.now().toString(), text: newTask, completed: false }, ...prev]);
    setNewTask('');
  };

  const toggleGrocery = (id: string) => {
    setGroceries(prev => prev.map(g => g.id === id ? { ...g, completed: !g.completed } : g));
  };

  const toggleTask = (id: string) => {
    setTasks(prev => prev.map(t => t.id === id ? { ...t, completed: !t.completed } : t));
  };

  const clearGroceries = () => setGroceries(prev => prev.filter(g => !g.completed));

  return (
    <div className="grid grid-cols-1 md:grid-cols-2 gap-8 h-full">
      {/* Grocery List */}
      <div className="flex flex-col">
        <div className="flex items-center justify-between mb-6">
          <h2 className="text-3xl font-bold">Groceries</h2>
          <button 
            onClick={clearGroceries}
            className="text-gray-400 hover:text-white flex items-center gap-2 text-sm font-bold uppercase tracking-wider"
          >
            <Trash2 size={16} />
            Clear Completed
          </button>
        </div>

        <div className="glass rounded-3xl p-4 flex gap-2 mb-6 shadow-lg">
          <input 
            value={newGrocery}
            onChange={(e) => setNewGrocery(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && addGrocery()}
            className="flex-1 bg-white/5 rounded-2xl p-4 outline-none border border-white/5 focus:border-green-500 transition-all text-lg"
            placeholder="Add item..."
          />
          <select 
            value={newAisle}
            onChange={(e) => setNewAisle(e.target.value)}
            className="bg-white/5 rounded-2xl p-4 outline-none border border-white/5 text-gray-300"
          >
            {AISLES.map(a => <option key={a} value={a} className="bg-neutral-900">{a}</option>)}
          </select>
          <button 
            onClick={addGrocery}
            className="bg-green-600 p-4 rounded-2xl hover:bg-green-500 transition-transform active:scale-95"
          >
            <Plus size={24} />
          </button>
        </div>

        <div className="flex-1 overflow-y-auto space-y-2 pr-2">
          {AISLES.map(aisle => {
            const items = groceries.filter(g => g.aisle === aisle);
            if (items.length === 0) return null;
            return (
              <div key={aisle} className="mb-4">
                <h4 className="text-[10px] font-bold text-gray-500 uppercase tracking-[0.2em] mb-2 px-4">{aisle}</h4>
                {items.map(item => (
                  <button
                    key={item.id}
                    onClick={() => toggleGrocery(item.id)}
                    className="w-full flex items-center gap-4 bg-white/5 p-4 rounded-2xl hover:bg-white/10 transition-colors mb-2 text-left group"
                  >
                    {item.completed ? <CheckCircle2 className="text-green-500" /> : <Circle className="text-gray-600 group-hover:text-gray-400" />}
                    <span className={`text-lg ${item.completed ? 'line-through text-gray-600' : 'text-gray-200'}`}>{item.text}</span>
                  </button>
                ))}
              </div>
            );
          })}
        </div>
      </div>

      {/* To-Do List */}
      <div className="flex flex-col">
        <h2 className="text-3xl font-bold mb-6">Family To-Do</h2>

        <div className="glass rounded-3xl p-4 flex gap-2 mb-6 shadow-lg">
          <input 
            value={newTask}
            onChange={(e) => setNewTask(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && addTask()}
            className="flex-1 bg-white/5 rounded-2xl p-4 outline-none border border-white/5 focus:border-blue-500 transition-all text-lg"
            placeholder="Add a chore..."
          />
          <button 
            onClick={addTask}
            className="bg-blue-600 p-4 rounded-2xl hover:bg-blue-500 transition-transform active:scale-95"
          >
            <Plus size={24} />
          </button>
        </div>

        <div className="flex-1 overflow-y-auto space-y-3 pr-2">
          {tasks.map(task => (
            <button
              key={task.id}
              onClick={() => toggleTask(task.id)}
              className="w-full flex items-center gap-4 bg-white/5 p-5 rounded-2xl hover:bg-white/10 transition-all text-left border border-white/5"
            >
              <div className={`w-8 h-8 rounded-full flex items-center justify-center border-2 transition-colors ${
                task.completed ? 'bg-blue-500 border-blue-500' : 'border-gray-700'
              }`}>
                {task.completed && <CheckCircle2 size={16} className="text-white" />}
              </div>
              <span className={`text-xl font-medium ${task.completed ? 'line-through text-gray-600' : 'text-gray-100'}`}>
                {task.text}
              </span>
            </button>
          ))}
          {tasks.length === 0 && <div className="text-center text-gray-600 mt-20 italic">No chores pending! Relax.</div>}
        </div>
      </div>
    </div>
  );
};

export default TasksView;

import React, { useState } from 'react';
import { MealPlan } from '../types';
import { Check, Edit2, Star } from 'lucide-react';

interface Props {
  meals: MealPlan[];
  setMeals: React.Dispatch<React.SetStateAction<MealPlan[]>>;
}

const FAVORITES = ["Tacos", "Spaghetti", "Grilled Salmon", "Stir Fry", "Pizza", "Roast Chicken", "Lentil Soup"];

const MealsView: React.FC<Props> = ({ meals, setMeals }) => {
  const [editing, setEditing] = useState<{ day: string, type: 'lunch' | 'dinner' } | null>(null);
  const [editValue, setEditValue] = useState('');

  const startEdit = (day: string, type: 'lunch' | 'dinner', current: string) => {
    setEditing({ day, type });
    setEditValue(current);
  };

  const saveEdit = () => {
    if (!editing) return;
    setMeals(prev => prev.map(m => 
      m.day === editing.day ? { ...m, [editing.type]: editValue } : m
    ));
    setEditing(null);
  };

  const selectFavorite = (fav: string) => {
    setEditValue(fav);
  };

  return (
    <div className="flex flex-col h-full">
      <div className="flex items-center justify-between mb-8">
        <h2 className="text-3xl font-bold">Weekly Meal Planner</h2>
        <div className="flex items-center gap-2 text-yellow-500">
          <Star size={20} fill="currentColor" />
          <span className="font-bold text-sm uppercase tracking-widest">Master Menu</span>
        </div>
      </div>

      <div className="grid grid-cols-1 gap-4 overflow-y-auto pb-8">
        {meals.map((item) => (
          <div key={item.day} className="glass rounded-3xl p-6 flex flex-col md:flex-row md:items-center gap-6 shadow-lg border border-white/5 transition-all hover:border-white/20">
            <div className="w-40">
              <h3 className="text-2xl font-bold text-blue-400">{item.day}</h3>
            </div>

            <div className="flex-1 grid grid-cols-1 md:grid-cols-2 gap-4">
              {/* Lunch Slot */}
              <button 
                onClick={() => startEdit(item.day, 'lunch', item.lunch)}
                className="bg-white/5 hover:bg-white/10 p-5 rounded-2xl text-left transition-all border border-transparent hover:border-blue-500/50 flex justify-between items-center"
              >
                <div>
                  <p className="text-[10px] font-bold text-gray-500 uppercase mb-1">Lunch</p>
                  <p className={`text-lg ${item.lunch ? 'text-white' : 'text-gray-700 italic'}`}>
                    {item.lunch || "Add lunch..."}
                  </p>
                </div>
                <Edit2 size={16} className="text-gray-600" />
              </button>

              {/* Dinner Slot */}
              <button 
                onClick={() => startEdit(item.day, 'dinner', item.dinner)}
                className="bg-white/5 hover:bg-white/10 p-5 rounded-2xl text-left transition-all border border-transparent hover:border-pink-500/50 flex justify-between items-center"
              >
                <div>
                  <p className="text-[10px] font-bold text-gray-500 uppercase mb-1">Dinner</p>
                  <p className={`text-lg ${item.dinner ? 'text-white' : 'text-gray-700 italic'}`}>
                    {item.dinner || "Add dinner..."}
                  </p>
                </div>
                <Edit2 size={16} className="text-gray-600" />
              </button>
            </div>
          </div>
        ))}
      </div>

      {editing && (
        <div className="fixed inset-0 bg-black/80 backdrop-blur-md flex items-center justify-center z-50 p-4">
          <div className="glass rounded-3xl p-8 w-full max-w-2xl border border-white/20 shadow-2xl">
            <div className="flex justify-between items-center mb-8">
              <h3 className="text-3xl font-bold">
                {editing.day} <span className="text-blue-500">{editing.type}</span>
              </h3>
              <button onClick={() => setEditing(null)} className="text-gray-500 hover:text-white">✕</button>
            </div>

            <div className="space-y-8">
              <input
                autoFocus
                value={editValue}
                onChange={(e) => setEditValue(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && saveEdit()}
                className="w-full bg-white/10 rounded-3xl p-8 text-4xl font-bold outline-none border border-white/10 focus:ring-4 ring-blue-500/20 text-center"
                placeholder="What's for meal?"
              />

