import React, { useState } from 'react';
import { GroceryItem, TaskItem, Member } from '../types';
import { AISLES } from '../constants';
import { Plus, Trash2, CheckCircle2, Circle, Coins, User } from 'lucide-react';

interface Props {
  groceries: GroceryItem[];
  setGroceries: React.Dispatch<React.SetStateAction<GroceryItem[]>>;
  tasks: TaskItem[];
  setTasks: React.Dispatch<React.SetStateAction<TaskItem[]>>;
  members: Member[];
  onToggleTask: (id: string) => void;
}

const TasksView: React.FC<Props> = ({ groceries, setGroceries, tasks, setTasks, members, onToggleTask }) => {
  const [newGrocery, setNewGrocery] = useState('');
  const [newAisle, setNewAisle] = useState('Produce');
  const [newTask, setNewTask] = useState('');
  const [taskAssignee, setTaskAssignee] = useState(members[0]?.name || '');
  const [taskPoints, setTaskPoints] = useState('10');

  const addGrocery = () => {
    if (!newGrocery) return;
    setGroceries(prev => [{ id: Date.now().toString(), text: newGrocery, aisle: newAisle, completed: false }, ...prev]);
    setNewGrocery('');
  };

  const addTask = () => {
    if (!newTask) return;
    setTasks(prev => [{ 
      id: Date.now().toString(), 
      text: newTask, 
      completed: false, 
      assignedTo: taskAssignee, 
      points: parseInt(taskPoints) || 10 
    }, ...prev]);
    setNewTask('');
  };

  const toggleGrocery = (id: string) => {
    setGroceries(prev => prev.map(g => g.id === id ? { ...g, completed: !g.completed } : g));
  };

  const clearGroceries = () => setGroceries(prev => prev.filter(g => !g.completed));

  return (
    <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 h-full">
      {/* Grocery List */}
      <div className="flex flex-col">
        <div className="flex items-center justify-between mb-6">
          <h2 className="text-3xl font-bold">Groceries</h2>
          <button 
            onClick={clearGroceries}
            className="text-gray-400 hover:text-white flex items-center gap-2 text-sm font-bold uppercase tracking-wider"
          >
            <Trash2 size={16} />
            Clear Completed
          </button>
        </div>

        <div className="glass rounded-3xl p-4 flex gap-2 mb-6 shadow-lg">
          <input 
            value={newGrocery}
            onChange={(e) => setNewGrocery(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && addGrocery()}
            className="flex-1 bg-white/5 rounded-2xl p-4 outline-none border border-white/5 focus:border-green-500 transition-all text-lg"
            placeholder="Add item..."
          />
          <select 
            value={newAisle}
            onChange={(e) => setNewAisle(e.target.value)}
            className="bg-neutral-900 rounded-2xl p-4 outline-none border border-white/5 text-gray-300"
          >
            {AISLES.map(a => <option key={a} value={a}>{a}</option>)}
          </select>
          <button 
            onClick={addGrocery}
            className="bg-green-600 p-4 rounded-2xl hover:bg-green-500 transition-transform active:scale-95 shrink-0"
          >
            <Plus size={24} />
          </button>
        </div>

        <div className="flex-1 overflow-y-auto space-y-2 pr-2">
          {AISLES.map(aisle => {
            const items = groceries.filter(g => g.aisle === aisle);
            if (items.length === 0) return null;
            return (
              <div key={aisle} className="mb-4">
                <h4 className="text-[10px] font-bold text-gray-500 uppercase tracking-[0.2em] mb-2 px-4">{aisle}</h4>
                {items.map(item => (
                  <button
                    key={item.id}
                    onClick={() => toggleGrocery(item.id)}
                    className="w-full flex items-center gap-4 bg-white/5 p-4 rounded-2xl hover:bg-white/10 transition-colors mb-2 text-left group"
                  >
                    {item.completed ? <CheckCircle2 className="text-green-500" /> : <Circle className="text-gray-600 group-hover:text-gray-400" />}
                    <span className={`text-lg ${item.completed ? 'line-through text-gray-600' : 'text-gray-200'}`}>{item.text}</span>
                  </button>
                ))}
              </div>
            );
          })}
        </div>
      </div>

      {/* To-Do List (Gamified) */}
      <div className="flex flex-col">
        <h2 className="text-3xl font-bold mb-6">Chore Chart</h2>

        <div className="glass rounded-3xl p-4 flex flex-col gap-3 mb-6 shadow-lg">
          <div className="flex gap-2">
            <input 
              value={newTask}
              onChange={(e) => setNewTask(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && addTask()}
              className="flex-1 bg-white/5 rounded-2xl p-4 outline-none border border-white/5 focus:border-blue-500 transition-all text-lg"
              placeholder="Assign a chore..."
            />
            <button 
              onClick={addTask}
              className="bg-blue-600 p-4 rounded-2xl hover:bg-blue-500 transition-transform active:scale-95 shrink-0"
            >
              <Plus size={24} />
            </button>
          </div>
          <div className="flex gap-3">
             <div className="flex-1 relative">
                <select 
                  value={taskAssignee}
                  onChange={(e) => setTaskAssignee(e.target.value)}
                  className="w-full bg-neutral-900 rounded-2xl p-3 pl-10 outline-none border border-white/5 text-gray-300 appearance-none"
                >
                  {members.map(m => <option key={m.id} value={m.name}>{m.name}</option>)}
                </select>
                <User size={16} className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-500" />
             </div>
             <div className="w-32 relative">
                <input 
                  type="number"
                  value={taskPoints}
                  onChange={(e) => setTaskPoints(e.target.value)}
                  className="w-full bg-neutral-900 rounded-2xl p-3 pl-10 outline-none border border-white/5 text-gray-300"
                  placeholder="Pts"
                />
                <Coins size={16} className="absolute left-4 top-1/2 -translate-y-1/2 text-yellow-500" />
             </div>
          </div>
        </div>

        <div className="flex-1 overflow-y-auto space-y-3 pr-2">
          {tasks.map(task => (
            <div
              key={task.id}
              className="w-full flex items-center justify-between gap-4 bg-white/5 p-5 rounded-2xl hover:bg-white/10 transition-all border border-white/5 group"
            >
              <button 
                onClick={() => onToggleTask(task.id)}
                className="flex items-center gap-4 text-left flex-1"
              >
                <div className={`w-8 h-8 rounded-full flex items-center justify-center border-2 transition-colors shrink-0 ${
                  task.completed ? 'bg-blue-500 border-blue-500' : 'border-gray-700'
                }`}>
                  {task.completed && <CheckCircle2 size={16} className="text-white" />}
                </div>
                <div>
                  <span className={`text-xl font-medium block ${task.completed ? 'line-through text-gray-600' : 'text-gray-100'}`}>
                    {task.text}
                  </span>
                  <div className="flex items-center gap-2 mt-1">
                    <span className="text-xs font-bold text-gray-500 uppercase tracking-widest">{task.assignedTo || 'Unassigned'}</span>
                    <span className="text-xs text-gray-600">•</span>
                    <div className="flex items-center gap-1 text-yellow-500/80 font-bold text-xs">
                       <Coins size={10} />
                       {task.points} pts
                    </div>
                  </div>
                </div>
              </button>

              <button 
                onClick={() => setTasks(prev => prev.filter(t => t.id !== task.id))}
                className="opacity-0 group-hover:opacity-100 p-2 text-gray-600 hover:text-red-400 transition-all"
              >
                <Trash2 size={18} />
              </button>
            </div>
          ))}
          {tasks.length === 0 && <div className="text-center text-gray-600 mt-10 italic">No chores assigned!</div>}
        </div>
      </div>
    </div>
  );
};

