        </button>
      </div>

      <div className="flex-1 overflow-y-auto space-y-6 pr-4">
        {AISLES.map(aisle => {
          const items = groceries.filter(g => g.aisle === aisle);
          if (items.length === 0) return null;
          return (
            <div key={aisle} className="animate-in fade-in slide-in-from-bottom-2 duration-300">
              <h4 className="text-xs font-bold text-gray-500 uppercase tracking-[0.3em] mb-4 ml-2">{aisle}</h4>
              <div className="grid gap-3">
                {items.map(item => (
                  <button
                    key={item.id}
                    onClick={() => toggleGrocery(item.id)}
                    className="w-full flex items-center gap-5 bg-white/5 p-5 rounded-2xl hover:bg-white/10 transition-all text-left group border border-transparent hover:border-white/10"
                  >
                    {item.completed ? (
                      <CheckCircle2 className="text-green-500 shrink-0" size={28} />
                    ) : (
                      <Circle className="text-gray-600 group-hover:text-gray-400 shrink-0" size={28} />
                    )}
                    <span className={`text-xl font-medium ${item.completed ? 'line-through text-gray-600' : 'text-gray-200'}`}>
                      {item.text}
                    </span>
                  </button>
                ))}
              </div>
            </div>
          );
        })}
        {groceries.length === 0 && (
          <div className="flex flex-col items-center justify-center h-64 text-gray-600 opacity-50">
            <ShoppingCart className="mb-4" size={64} />
            <p className="text-xl italic">The fridge is full! Add something to the list.</p>
          </div>
        )}
      </div>
    </div>
  );
};

export default TasksView;

import React, { useState, useEffect } from 'react';
import { NAV_ITEMS } from './constants';
import { View, CalendarEvent, GroceryItem, TaskItem, MealPlan, Category, Member } from './types';
import Dashboard from './components/Dashboard';
import CalendarView from './components/CalendarView';
import TasksView from './components/TasksView';
import ChoresView from './components/ChoresView';
import MealsView from './components/MealsView';
import InfoHub from './components/InfoHub';

const App: React.FC = () => {
  const [activeView, setActiveView] = useState<View>('dashboard');

  const [members, setMembers] = useState<Member[]>(() => {
    const saved = localStorage.getItem('family_members');
    return saved ? JSON.parse(saved) : [
      { id: '1', name: 'Otto', points: 45, avatarColor: 'bg-blue-500' },
      { id: '2', name: 'Future Baby', points: 0, avatarColor: 'bg-pink-500' },
      { id: '3', name: 'Dad', points: 120, avatarColor: 'bg-green-500' },
      { id: '4', name: 'Mom', points: 150, avatarColor: 'bg-purple-500' },
    ];
  });

  const [events, setEvents] = useState<CalendarEvent[]>(() => {
    const saved = localStorage.getItem('family_events');
    return saved ? JSON.parse(saved) : [
      { id: '1', title: 'Soccer Practice', date: new Date().toISOString().split('T')[0], category: Category.KIDS },
      { id: '2', title: 'Dinner with Grandparents', date: new Date().toISOString().split('T')[0], category: Category.FAMILY },
    ];
  });

  const [groceries, setGroceries] = useState<GroceryItem[]>(() => {
    const saved = localStorage.getItem('family_groceries');
    return saved ? JSON.parse(saved) : [
      { id: '1', text: 'Milk', completed: false, aisle: 'Dairy' },
      { id: '2', text: 'Apples', completed: true, aisle: 'Produce' },
    ];
  });

  const [tasks, setTasks] = useState<TaskItem[]>(() => {
    const saved = localStorage.getItem('family_tasks');
    return saved ? JSON.parse(saved) : [
      { id: '1', text: 'Take out trash', completed: false, assignedTo: 'Otto', points: 10 },
      { id: '2', text: 'Load dishwasher', completed: false, assignedTo: 'Mom', points: 15 },
    ];
  });

  const [meals, setMeals] = useState<MealPlan[]>(() => {
    const saved = localStorage.getItem('family_meals');
    if (saved) return JSON.parse(saved);
    const days = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'];
    return days.map(day => ({ day, lunch: '', dinner: '' }));
  });

  const [quickNote, setQuickNote] = useState(() => localStorage.getItem('family_note') || "Dad is napping. Keep it quiet!");

  useEffect(() => localStorage.setItem('family_events', JSON.stringify(events)), [events]);
  useEffect(() => localStorage.setItem('family_groceries', JSON.stringify(groceries)), [groceries]);
  useEffect(() => localStorage.setItem('family_tasks', JSON.stringify(tasks)), [tasks]);
  useEffect(() => localStorage.setItem('family_meals', JSON.stringify(meals)), [meals]);
  useEffect(() => localStorage.setItem('family_note', quickNote), [quickNote]);
  useEffect(() => localStorage.setItem('family_members', JSON.stringify(members)), [members]);

  const handleToggleTask = (taskId: string) => {
    setTasks(prev => prev.map(t => {
      if (t.id === taskId) {
        const isNowCompleted = !t.completed;
        if (isNowCompleted && t.assignedTo) {
          setMembers(mPrev => mPrev.map(m => 
            m.name === t.assignedTo ? { ...m, points: m.points + t.points } : m
          ));
        } else if (!isNowCompleted && t.assignedTo) {
          setMembers(mPrev => mPrev.map(m => 
            m.name === t.assignedTo ? { ...m, points: Math.max(0, m.points - t.points) } : m
          ));
        }
        return { ...t, completed: isNowCompleted };
      }
      return t;
    }));
  };

  const renderContent = () => {
    switch (activeView) {
      case 'dashboard':
        return <Dashboard events={events} meals={meals} quickNote={quickNote} setQuickNote={setQuickNote} members={members} />;
      case 'calendar':
        return <CalendarView events={events} setEvents={setEvents} />;
      case 'groceries':
        return <TasksView groceries={groceries} setGroceries={setGroceries} />;
      case 'chores':
        return <ChoresView tasks={tasks} setTasks={setTasks} members={members} onToggleTask={handleToggleTask} />;
      case 'meals':
        return <MealsView meals={meals} setMeals={setMeals} />;
      case 'info':
        return <InfoHub />;
      default:
        return <Dashboard events={events} meals={meals} quickNote={quickNote} setQuickNote={setQuickNote} members={members} />;
    }
  };

  return (
    <div className="flex h-screen w-screen overflow-hidden bg-black text-white p-4 gap-4">
      <nav className="w-24 md:w-32 flex flex-col items-center glass rounded-3xl py-8 space-y-4">
        <div className="mb-4">
          <div className="w-12 h-12 bg-gradient-to-tr from-blue-500 to-indigo-600 rounded-2xl flex items-center justify-center shadow-lg shadow-blue-500/20">
            <span className="font-bold text-xl">F</span>
          </div>
        </div>
        {NAV_ITEMS.map((item) => (
          <button
            key={item.id}
            onClick={() => setActiveView(item.id)}
            className={`p-4 rounded-2xl transition-all duration-200 flex flex-col items-center gap-2 w-20 ${
              activeView === item.id 
                ? 'glass-active text-blue-400 shadow-inner' 
                : 'text-gray-400 hover:text-white hover:bg-white/5'
            }`}
          >
            {item.icon}
            <span className="text-[10px] font-medium uppercase tracking-wider text-center leading-tight">{item.label}</span>
          </button>
        ))}
      </nav>

      <main className="flex-1 glass rounded-3xl overflow-hidden relative">
        <div className="h-full w-full overflow-y-auto p-8">
          {renderContent()}
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { TaskItem, Member } from '../types';
import { Plus, Trash2, CheckCircle2, Circle, Coins, User, Trophy, TrendingUp } from 'lucide-react';

interface Props {
  tasks: TaskItem[];
  setTasks: React.Dispatch<React.SetStateAction<TaskItem[]>>;
  members: Member[];
  onToggleTask: (id: string) => void;
}

const ChoresView: React.FC<Props> = ({ tasks, setTasks, members, onToggleTask }) => {
  const [newTask, setNewTask] = useState('');
  const [taskAssignee, setTaskAssignee] = useState(members[0]?.name || '');
  const [taskPoints, setTaskPoints] = useState('15');

  const addTask = () => {
    if (!newTask) return;
    setTasks(prev => [{ 
      id: Date.now().toString(), 
      text: newTask, 
      completed: false, 
      assignedTo: taskAssignee, 
      points: parseInt(taskPoints) || 10 
    }, ...prev]);
    setNewTask('');
  };

  const sortedMembers = [...members].sort((a, b) => b.points - a.points);

  return (
    <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 h-full">
      {/* Left Column: Input and Tasks (8 cols) */}
      <div className="lg:col-span-8 flex flex-col">
        <div className="flex items-center justify-between mb-8">
          <h2 className="text-4xl font-bold flex items-center gap-4">
            Family Chore Chart
            <span className="text-sm bg-blue-500/20 text-blue-400 px-3 py-1 rounded-full border border-blue-500/20 font-bold uppercase tracking-widest">
              Earn Points
            </span>
          </h2>
        </div>

        {/* Input Area */}
        <div className="glass rounded-3xl p-6 flex flex-col gap-4 mb-8 shadow-xl border-white/10">
          <div className="flex gap-4">
            <input 
              value={newTask}
              onChange={(e) => setNewTask(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && addTask()}
              className="flex-1 bg-white/5 rounded-2xl p-5 outline-none border border-white/5 focus:border-blue-500 transition-all text-xl"
              placeholder="What needs to be done?"
            />
            <button 
              onClick={addTask}
              className="bg-blue-600 px-10 rounded-2xl hover:bg-blue-500 transition-transform active:scale-95 shrink-0 flex items-center justify-center shadow-lg shadow-blue-900/20 font-bold"
            >
              Assign
            </button>
          </div>
          <div className="flex gap-4">
             <div className="flex-1 relative">
                <label className="text-[10px] font-bold text-gray-500 uppercase tracking-widest mb-1 block ml-1">Assignee</label>
                <div className="relative">
                  <select 
                    value={taskAssignee}
                    onChange={(e) => setTaskAssignee(e.target.value)}
                    className="w-full bg-neutral-900 rounded-2xl p-4 pl-12 outline-none border border-white/5 text-gray-300 appearance-none focus:border-blue-500/50"
                  >
                    {members.map(m => <option key={m.id} value={m.name}>{m.name}</option>)}
                  </select>
                  <User size={20} className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-500" />
                </div>
             </div>
             <div className="w-40">
                <label className="text-[10px] font-bold text-gray-500 uppercase tracking-widest mb-1 block ml-1">Reward</label>
                <div className="relative">
                  <input 
                    type="number"
                    value={taskPoints}
                    onChange={(e) => setTaskPoints(e.target.value)}
                    className="w-full bg-neutral-900 rounded-2xl p-4 pl-12 outline-none border border-white/5 text-gray-300 focus:border-yellow-500/50"
                  />
                  <Coins size={20} className="absolute left-4 top-1/2 -translate-y-1/2 text-yellow-500" />
                  <span className="absolute right-4 top-1/2 -translate-y-1/2 text-xs font-bold text-gray-600">PTS</span>
                </div>
             </div>
          </div>
        </div>

        {/* Task List */}
        <div className="flex-1 overflow-y-auto space-y-4 pr-4">
          {tasks.map(task => (
            <div
              key={task.id}
              className={`w-full flex items-center justify-between gap-4 p-6 rounded-3xl transition-all border group relative ${
                task.completed ? 'bg-white/5 border-transparent opacity-60' : 'bg-white/5 border-white/5 hover:bg-white/10 hover:border-white/10'
              }`}
            >
              <button 
                onClick={() => onToggleTask(task.id)}
                className="flex items-center gap-6 text-left flex-1"
              >
                <div className={`w-10 h-10 rounded-full flex items-center justify-center border-2 transition-all shrink-0 ${
                  task.completed ? 'bg-blue-500 border-blue-500 scale-90' : 'border-gray-700 group-hover:border-blue-500'
                }`}>
                  {task.completed && <CheckCircle2 size={24} className="text-white" />}
                </div>
                <div>
                  <span className={`text-2xl font-semibold block ${task.completed ? 'line-through text-gray-500' : 'text-gray-100'}`}>
                    {task.text}
                  </span>
                  <div className="flex items-center gap-4 mt-2">
                    <div className="flex items-center gap-2">
                      <div className={`w-5 h-5 rounded-full ${members.find(m => m.name === task.assignedTo)?.avatarColor || 'bg-gray-500'} flex items-center justify-center text-[8px] font-bold`}>
                        {task.assignedTo?.[0]}
                      </div>
                      <span className="text-xs font-bold text-gray-400 uppercase tracking-widest">{task.assignedTo}</span>
                    </div>
                    <div className="flex items-center gap-1.5 text-yellow-500 font-bold text-sm bg-yellow-500/10 px-3 py-1 rounded-full border border-yellow-500/10">
                       <Coins size={14} />
                       {task.points} Points
                    </div>
                  </div>
                </div>
              </button>

              <button 
                onClick={() => setTasks(prev => prev.filter(t => t.id !== task.id))}
                className="opacity-0 group-hover:opacity-100 p-3 text-gray-600 hover:text-red-400 transition-all bg-white/5 rounded-xl"
              >
                <Trash2 size={20} />
              </button>
            </div>
          ))}
          {tasks.length === 0 && (
            <div className="flex flex-col items-center justify-center h-64 text-gray-600">
               <Trophy className="mb-4 opacity-20" size={80} />
               <p className="text-xl italic opacity-50">All chores complete! Enjoy the freedom.</p>
            </div>
          )}
        </div>
      </div>

      {/* Right Column: Leaderboard (4 cols) */}
      <div className="lg:col-span-4 flex flex-col gap-6">
        <div className="glass rounded-3xl p-8 shadow-2xl border-white/5 sticky top-0">
          <div className="flex items-center gap-3 mb-8">
            <TrendingUp className="text-green-500" />
            <h3 className="text-2xl font-bold">Hall of Fame</h3>
          </div>

          <div className="space-y-6">
            {sortedMembers.map((member, idx) => (
              <div key={member.id} className="relative">
                <div className="flex items-center justify-between mb-2">
                  <div className="flex items-center gap-4">
                    <div className="relative">
                      <div className={`w-12 h-12 rounded-2xl ${member.avatarColor} flex items-center justify-center font-bold text-xl shadow-lg`}>
                        {member.name[0]}
                      </div>
                      {idx === 0 && (
                        <div className="absolute -top-3 -right-3 rotate-12 text-2xl">👑</div>
                      )}
                    </div>
                    <div>
                      <p className="font-bold text-lg leading-tight">{member.name}</p>
                      <p className="text-xs text-gray-500 font-bold uppercase tracking-widest">Level {Math.floor(member.points / 100) + 1}</p>
                    </div>
                  </div>
                  <div className="text-right">
                    <span className="text-2xl font-black text-white">{member.points}</span>
                    <span className="text-[10px] block text-yellow-500 font-bold uppercase tracking-widest">Points</span>
                  </div>
                </div>
                {/* Progress bar to next "Level" */}
                <div className="h-2 w-full bg-white/5 rounded-full overflow-hidden border border-white/5">
                  <div 
                    className={`h-full ${member.avatarColor} transition-all duration-1000 shadow-[0_0_10px_rgba(255,255,255,0.2)]`}
                    style={{ width: `${(member.points % 100)}%` }}
                  ></div>
                </div>
              </div>
            ))}
          </div>

          <div className="mt-12 p-6 bg-gradient-to-br from-blue-500/10 to-indigo-500/10 rounded-3xl border border-blue-500/10">
            <h4 className="font-bold text-blue-400 text-sm mb-2 uppercase tracking-widest">Next Reward</h4>
            <p className="text-white font-medium text-lg leading-snug">Otto is only a few points away from Picking Movie Night!</p>
          </div>
        </div>
      </div>
    </div>
  );
};

export default ChoresView;
